<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {api,apiBaseUrl} from '../lib/api'
import {asset,assets} from '../lib/assets'
const props=defineProps<{token:string}>()
type Media={id:string;url:string;kind:string;src?:string}
type Moment={id:string;userId:string;content:string;visibility:string;category:string;createdAt:string;attachments:Media[]}
type Card={id:string;url:string;type:string;visibility:string;isPrimary:boolean;src?:string}
const cards=ref<Card[]>([]),posts=ref<Moment[]>([]),owner=ref(''),screen=ref(''),sheet=ref(''),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(false),more=ref(false)
const card=ref<Card>(),moment=ref<Moment>(),type=ref('portrait'),category=ref('All'),text=ref(''),audience=ref('everyone'),attachments=ref<Media[]>([]),picker=ref<HTMLInputElement>(),cardPicker=ref<HTMLInputElement>()
const categories=['Life','Portrait','Style','Outfit'],postCategory=ref('Life')
const types=['portrait','physique','outfit','life'],visibility=[['everyone','Everyone'],['friends','Friends'],['only_me','Only me']]
const stickers=assets.filter(a=>a.category==='06-stickers').slice(0,24)
const urls:string[]=[]
const draftKey=computed(()=>`maugo-d5-draft-${owner.value}`)
const count=computed(()=>[...text.value].length)
const visible=computed(()=>posts.value)
const state=computed(()=>sheet.value|| (screen.value==='compose'?(attachments.value.length?'moment-photo':text.value?'moment-draft':'moment-empty'):screen.value==='detail'?'moment-detail':screen.value==='moments'?(!posts.value.length?(category.value==='All'?'moments-empty':'moments-category-empty'):'moments-list'):'image-cards'))
const headers=()=>({Authorization:`Bearer ${props.token}`})
async function request<T>(path:string,method='GET',body?:object){return api<T>(path,{method,headers:{...headers(),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})})}
async function hydrate(media:{url:string;src?:string}){const response=await fetch(apiBaseUrl+media.url,{headers:headers()});if(!response.ok)throw Error(`Photo unavailable (${response.status})`);media.src=URL.createObjectURL(await response.blob());urls.push(media.src)}
async function loadCards(){cards.value=(await request<{items:Card[]}>('/users/me/image-cards')).items;await Promise.all(cards.value.map(hydrate))}
async function loadPosts(append=false){const rows=(await request<{items:Moment[]}>(`/posts?userId=${owner.value}&category=${category.value}&limit=20&offset=${append?posts.value.length:0}`)).items;await Promise.all(rows.flatMap(p=>p.attachments).map(hydrate));posts.value=append?[...posts.value,...rows]:rows;more.value=rows.length===20}
async function act(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await work()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function init(){loading.value=true;await act(async()=>{owner.value=(await request<{id:string}>('/profiles/me')).id;await loadCards()});loading.value=false}
onMounted(init)
onUnmounted(()=>urls.forEach(url=>URL.revokeObjectURL(url)))
function label(value:string){return visibility.find(v=>v[0]===value)?.[1]||value}
function openMoments(){screen.value='moments';notice.value='';void act(()=>loadPosts())}
function filterCategory(value:string){if(busy.value)return;category.value=value;void act(()=>loadPosts())}
async function patchMoment(body:object){await act(async()=>{await request(`/posts/${moment.value!.id}`,'PATCH',body);const row=await request<Moment>(`/posts/${moment.value!.id}`);await Promise.all(row.attachments.map(hydrate));moment.value=row;await loadPosts();sheet.value=''})}
function compose(){const draft=JSON.parse(localStorage.getItem(draftKey.value)||'null');postCategory.value=draft?.category||'Life';text.value=draft?.text||'';audience.value=draft?.visibility||'everyone';attachments.value=draft?.attachments||[];screen.value='compose';notice.value='';void act(async()=>{await Promise.all(attachments.value.map(hydrate))})}
function back(){if(busy.value)return;if(sheet.value){sheet.value='';return}if(screen.value==='compose'&&(text.value.trim()||attachments.value.length)){sheet.value='moment-leave';return}screen.value=screen.value==='detail'||screen.value==='compose'?'moments':''}
function leave(keep:boolean){if(keep)localStorage.setItem(draftKey.value,JSON.stringify({text:text.value,category:postCategory.value,visibility:audience.value,attachments:attachments.value.map(({id,url,kind})=>({id,url,kind}))}));else localStorage.removeItem(draftKey.value);text.value='';attachments.value=[];sheet.value='';screen.value='moments'}
async function upload(file:File){const allowed=['image/png','image/jpeg','image/webp','video/mp4','video/webm','audio/ogg','audio/wav','audio/mpeg'];if(!allowed.includes(file.type)||file.size>=(file.type.startsWith('video/')?30:10)*1024*1024)throw Error('Use PNG, JPEG, WebP, MP4, WebM, OGG, WAV or MP3 below 10 MB (video below 30 MB).');return api<Media>(`/media/uploads?${new URLSearchParams({purpose:'post',filename:file.name})}`,{method:'POST',headers:{...headers(),'Content-Type':file.type},body:file})}
async function chooseFiles(event:Event){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';if(attachments.value.length+files.length>6){error.value='You can add up to 6 attachments.';return}await act(async()=>{for(const file of files){const media=await upload(file);await hydrate(media);attachments.value.push(media)}})}
async function sticker(name:string){if(attachments.value.length>=6){error.value='You can add up to 6 attachments.';return}await act(async()=>{const blob=await(await fetch(asset(name))).blob(),media=await upload(new File([blob],'sticker.png',{type:'image/png'}));await hydrate(media);attachments.value.push(media);sheet.value=''})}
async function uploadCard(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;await act(async()=>{if(!file.type.startsWith('image/'))throw Error('Choose an image.');const media=await upload(file);await request('/users/me/image-cards','POST',{mediaId:media.id,type:type.value});await loadCards();sheet.value='';notice.value='Image card published.'})}
function selectType(value:string){type.value=value;if(sheet.value==='card-change-type'){void patchCard({type:value});return}cardPicker.value!.click()}
async function patchCard(body:object){await act(async()=>{await request(`/users/me/image-cards/${card.value!.id}`,'PATCH',body);await loadCards();sheet.value=''})}
async function publish(){if(count.value>1000||(!text.value.trim()&&!attachments.value.length))return;await act(async()=>{const saved=await request<Moment>('/posts','POST',{content:text.value,mediaIds:attachments.value.map(a=>a.id),category:postCategory.value,visibility:audience.value});localStorage.removeItem(draftKey.value);text.value='';attachments.value=[];await loadPosts();screen.value='moments';notice.value='Moment published.';moment.value=saved})}
async function detail(id:string){await act(async()=>{const row=await request<Moment>(`/posts/${id}`);await Promise.all(row.attachments.map(hydrate));moment.value=row;screen.value='detail'})}
async function remove(){await act(async()=>{if(sheet.value==='card-remove'){await request(`/users/me/image-cards/${card.value!.id}`,'DELETE');await loadCards()}else{await request(`/posts/${moment.value!.id}`,'DELETE');await loadPosts();screen.value='moments'}sheet.value='';notice.value='Deleted.'})}
</script>
<template>
<section class="d5" :data-state="state">
<p v-if="error" role="alert">{{error}} <button :disabled="busy" @click="screen?act(()=>loadPosts()):init()">Retry</button></p>
<p v-if="notice" role="status">{{notice}}</p>
<template v-if="!screen"><div class="section-heading"><h2>Image cards</h2><slot name="visibility" /></div><p v-if="loading">Loading…</p><div class="card-grid"><button v-for="c in cards" :key="c.id" :data-profile-moment="c.id" class="image-card" @click="card=c;sheet='card-options'"><img :src="c.src" alt="Image card"><span>{{c.type}}</span><small>{{c.isPrimary?'Main · ':''}}{{label(c.visibility)}}</small></button><button id="upload-image-card" class="upload-card" :disabled="busy||cards.length>=8||!owner" @click="sheet='card-type'"><b>＋</b><small>Upload a photo</small></button></div><p v-if="!loading&&!cards.length" class="hint">No photos uploaded yet.</p><div class="profile-card-actions"><button id="profile-moments" @click="openMoments">My moments ›</button><button id="new-profile-moment" class="compose-link" :disabled="!owner" @click="compose"><span aria-hidden="true">＋</span><span class="compose-caption"> A little moment</span></button></div></template>
<Transition name="d5-page"><section v-if="screen" class="d5-page" :class="{'moments-compose':screen==='compose','moments-has-media':attachments.length}" @keydown.esc.stop="back"><header><button id="d5-back" aria-label="Back from moments" :disabled="busy" @click="back">‹</button><h1>{{screen==='compose'?'A little moment':screen==='detail'?'Moment':'My moments'}}</h1><button v-if="screen==='moments'" id="new-moment" aria-label="New moment" @click="compose">＋</button><span v-else></span></header><div class="page-body"><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="screen==='compose'"><textarea id="moment-text" v-model="text" aria-label="Moment text" placeholder="What is on your mind?" :disabled="busy"></textarea><small class="counter" :class="{invalid:count>1000}">{{count}} / 1000</small><div class="media-grid"><div v-for="(a,i) in attachments" :key="a.id"><img v-if="a.kind==='image'" :src="a.src" alt="Attachment"><video v-else-if="a.kind==='video'" :src="a.src" controls></video><audio v-else :src="a.src" controls></audio><button :disabled="busy" :aria-label="`Remove attachment ${i+1}`" @click="attachments.splice(i,1)">×</button></div></div><div class="tools"><button id="moment-photo" :disabled="busy||attachments.length>=6" @click="picker!.click()"><span class="moments-en">▧ Media</span><span class="moments-ko">▧ 미디어</span></button><button id="moment-sticker" :disabled="busy||attachments.length>=6" @click="sheet='moment-stickers'"><span class="moments-en">☺ Stickers</span><span class="moments-ko">☺ 스티커</span></button></div><button id="moment-audience" class="row" :disabled="busy" @click="sheet='moment-visibility'">Who can see this? <small>{{label(audience)}} ›</small></button><span v-if="screen==='compose'" class="moments-category-label"><span class="moments-en"><span class="moments-en">Category</span><span class="moments-ko">카테고리</span></span><span class="moments-ko">카테고리</span></span><button id="compose-category" class="row" :disabled="busy" @click="sheet='compose-category'">Category <small>{{postCategory}} ›</small></button><p class="hint"><span class="moments-en">Up to 6 attachments. Visibility is enforced when shared.</span><span class="moments-ko">첨부 파일은 최대 6개입니다. 공유 시 공개 범위가 적용돼요.</span></p><button id="save-moment" class="primary ui-button ui-button--cards-delete" :disabled="busy||count>1000||(!text.trim()&&!attachments.length)" @click="publish"><span class="moments-en">{{busy?'Publishing…':'Publish moment'}}</span><span class="moments-ko">{{busy?'게시 중…':'순간 게시'}}</span></button></template>
<template v-else><nav v-if="screen==='moments'" class="categories"><button v-for="c in ['All','Portrait','Style','Outfit','Life']" :key="c" :aria-pressed="category===c"  :disabled="busy" @click="filterCategory(c)">{{c}}</button></nav><Transition name="d5-item" mode="out-in"><div v-if="screen==='moments'&&!visible.length&&!busy" :key="category" class="empty"><img :src="asset('02-bird-static/female-4')" alt=""><h3><span class="moments-en">Keep a little moment here.</span><span class="moments-ko">작은 순간을 여기에 간직하세요.</span></h3><p><span class="moments-en">Every connection starts with a little hello.</span><span class="moments-ko">모든 인연은 작은 인사로 시작돼요.</span></p></div></Transition><TransitionGroup name="d5-item"><article v-for="p in screen==='detail'&&moment?[moment]:visible" :key="p.id" class="moment-card"><header><small>{{new Date(p.createdAt).toLocaleDateString()}} · {{label(p.visibility)}} · {{p.category}}</small><button v-if="p.userId===owner" data-more aria-label="Moment options" @click="moment=p;sheet='moment-options'">•••</button></header><button class="moment-content" @click="screen==='moments'&&detail(p.id)">{{p.content}}</button><div class="media-grid"><template v-for="a in p.attachments" :key="a.id"><img v-if="a.kind==='image'" :src="a.src" alt="Moment photo" @click="screen==='moments'&&detail(p.id)"><video v-else-if="a.kind==='video'" :src="a.src" controls></video><audio v-else :src="a.src" controls></audio></template></div><button v-if="screen==='moments'" class="detail-link" @click="detail(p.id)"><span class="moments-en">View moment ›</span><span class="moments-ko">순간 보기 ›</span></button></article></TransitionGroup><button v-if="screen==='moments'&&more" :disabled="busy" class="row" @click="act(()=>loadPosts(true))"><span class="moments-en">Load more</span><span class="moments-ko">더 보기</span></button></template>
</div></section></Transition>
<input ref="picker" type="file" multiple accept="image/png,image/jpeg,image/webp,video/mp4,video/webm,audio/ogg,audio/wav,audio/mpeg" hidden @change="chooseFiles"><input ref="cardPicker" type="file" accept="image/png,image/jpeg,image/webp" hidden @change="uploadCard">
<Transition name="d5-sheet"><div v-if="sheet.startsWith('card-')" class="cards-overlay" :class="'cards-'+sheet" @click.self="!busy&&(sheet='')">
<section v-if="sheet==='card-remove'" class="cards-underlay ui-sheet ui-sheet--cards" aria-hidden="true" inert><div class="ui-sheet__grabber"></div><h2 class="cards-title"><span class="cards-en">Image card</span><span class="cards-ko">이미지 카드</span></h2><span class="cards-close ui-icon-button ui-icon-button--cards">×</span><div class="cards-options"><div class="ui-row ui-row--cards"><span class="cards-en">View photo</span><span class="cards-ko">사진 보기</span><span class="ui-chevron">›</span></div><div class="ui-row ui-row--cards"><span class="cards-en">Photo type</span><span class="cards-ko">사진 유형</span><small>{{card!.type}}</small><span class="ui-chevron">›</span></div><div class="ui-row ui-row--cards"><span class="cards-en">Visibility</span><span class="cards-ko">공개 범위</span><small>{{label(card!.visibility)}}</small><span class="ui-chevron">›</span></div><div class="ui-row ui-row--cards ui-row--cards-danger"><span class="cards-en">Remove card</span><span class="cards-ko">카드 삭제</span><span class="ui-chevron">›</span></div></div></section><div v-if="sheet==='card-remove'" class="cards-confirm-veil"></div>
<section :key="sheet" role="dialog" aria-modal="true" :aria-label="sheet" class="cards-panel ui-sheet ui-sheet--cards" :class="{'ui-dialog ui-dialog--cards':sheet==='card-remove'}">
<div v-if="sheet!=='card-remove'" class="ui-sheet__grabber"></div>
<button class="cards-close ui-icon-button ui-icon-button--cards" aria-label="Close D5 dialog" :disabled="busy" @click="sheet=''">×</button>
<template v-if="sheet==='card-type'||sheet==='card-change-type'"><h2 class="cards-title"><span class="cards-en">Photo type</span><span class="cards-ko">사진 유형</span></h2><div class="type-options cards-types"><button v-for="t in types" :key="t" class="ui-card-type" :data-card-type="t" :disabled="busy" @click="selectType(t)"><span class="cards-en">{{t}}</span><span class="cards-ko">{{({portrait:'인물',physique:'체형',outfit:'옷차림',life:'일상'})[t]}}</span></button></div><button class="cards-cancel ui-button ui-button--cards-secondary" :disabled="busy" @click="sheet=''"><span class="cards-en">Cancel</span><span class="cards-ko">취소</span></button></template>
<template v-else-if="sheet==='card-options'"><h2 class="cards-title"><span class="cards-en">Image card</span><span class="cards-ko">이미지 카드</span></h2><div class="cards-options"><button id="card-view" class="ui-row ui-row--cards" @click="sheet='card-preview'"><span class="cards-en">View photo</span><span class="cards-ko">사진 보기</span><span class="ui-chevron">›</span></button><button id="card-type" class="ui-row ui-row--cards" @click="sheet='card-change-type'"><span class="cards-en">Photo type</span><span class="cards-ko">사진 유형</span><small>{{card!.type}}</small><span class="ui-chevron">›</span></button><button id="card-visibility" class="ui-row ui-row--cards" @click="sheet='card-visibility'"><span class="cards-en">Visibility</span><span class="cards-ko">공개 범위</span><small>{{label(card!.visibility)}}</small><span class="ui-chevron">›</span></button><button id="card-remove" class="ui-row ui-row--cards ui-row--cards-danger" @click="sheet='card-remove'"><span class="cards-en">Remove card</span><span class="cards-ko">카드 삭제</span><span class="ui-chevron">›</span></button></div><button class="cards-primary-action ui-button ui-button--text" :disabled="busy||card!.isPrimary" @click="patchCard({isPrimary:true})">{{card!.isPrimary?'Main photo':'Set as main photo'}}</button></template>
<template v-else-if="sheet==='card-preview'"><h2 class="cards-title"><span class="cards-en">Photo</span><span class="cards-ko">사진</span></h2><img class="preview cards-preview" :src="card!.src" alt="Image card preview"><p class="cards-caption">{{card!.type}}</p></template>
<template v-else-if="sheet==='card-visibility'"><h2 class="cards-title"><span class="cards-en">Who can see this?</span><span class="cards-ko">누가 볼 수 있나요?</span></h2><div class="cards-audience"><button v-for="v in visibility" :key="v[0]" class="ui-row ui-row--cards-audience" :aria-pressed="card!.visibility===v[0]" :data-visibility="v[0]" :disabled="busy" @click="patchCard({visibility:v[0]})"><span class="cards-en">{{v[1]}}</span><span class="cards-ko">{{({everyone:'모두',friends:'친구',only_me:'나만'})[v[0]!]}}</span><b>{{card!.visibility===v[0]?'✓':''}}</b></button></div></template>
<template v-else-if="sheet==='card-remove'"><h2 class="cards-title"><span class="cards-en">Remove this photo?</span><span class="cards-ko">이 사진을 삭제할까요?</span></h2><p class="cards-description"><span class="cards-en">This removes the image card from your profile.</span><span class="cards-ko">프로필에서 이미지 카드가 삭제됩니다.</span></p><button id="d5-confirm-delete" class="cards-delete ui-button ui-button--cards-delete" :disabled="busy" @click="remove"><span class="cards-en">Delete</span><span class="cards-ko">삭제</span></button><button class="cards-cancel ui-button ui-button--cards-text" :disabled="busy" @click="sheet=''"><span class="cards-en">Cancel</span><span class="cards-ko">취소</span></button></template><p v-if="error" role="alert">{{error}}</p>
</section></div></Transition>
<Transition name="d5-sheet"><div v-if="sheet&&!sheet.startsWith('card-')" class="moments-overlay" :class="'moments-'+sheet" @click.self="!busy&&(sheet='')"><Transition name="d5-panel" mode="out-in"><section :key="sheet" role="dialog" aria-modal="true" :aria-label="sheet" class="sheet" :data-panel="['moment-leave','moment-delete'].includes(sheet)?'dialog':sheet==='moment-stickers'?'stickers':'sheet'"><div v-if="!['moment-leave','moment-delete','moment-stickers'].includes(sheet)" class="ui-sheet__grabber"></div><button class="close ui-icon-button ui-icon-button--cards" aria-label="Close D5 dialog" :disabled="busy" @click="sheet=''">×</button>
<template v-if="sheet==='card-visibility'||sheet==='moment-visibility'||sheet==='post-visibility'"><h2><span class="moments-en">Who can see this?</span><span class="moments-ko">누가 볼 수 있나요?</span></h2><button v-for="v in visibility" :key="v[0]" class="row ui-row ui-row--cards-audience" :aria-pressed="(sheet==='post-visibility'?moment!.visibility:audience)===v[0]" :data-visibility="v[0]" :disabled="busy" @click="sheet==='card-visibility'?patchCard({visibility:v[0]}):sheet==='post-visibility'?patchMoment({visibility:v[0]}):(audience=v[0]! ,sheet='')">{{v[1]}} <small>{{(sheet==='card-visibility'?card!.visibility:sheet==='post-visibility'?moment!.visibility:audience)===v[0]?'✓':''}}</small></button><p><span class="moments-en">Friends are people with a collected reply.</span><span class="moments-ko">답장을 받은 사람들이 친구예요.</span></p></template>
<template v-else-if="sheet==='post-category'||sheet==='compose-category'"><h2><span class="moments-en">Category</span><span class="moments-ko">카테고리</span></h2><button v-for="c in categories" :key="c" class="row" :data-post-category="c" :disabled="busy" @click="sheet==='post-category'?patchMoment({category:c}):(postCategory=c,sheet='')">{{c}} <small>{{(sheet==='post-category'?moment!.category:postCategory)===c?'✓':''}}</small></button></template>
<template v-else-if="sheet==='moment-stickers'"><h2><span class="moments-en">A little expression</span><span class="moments-ko">작은 감정 표현</span></h2><div class="stickers ui-sticker-grid"><button v-for="s in stickers" :key="s.name" class="ui-sticker-option" :disabled="busy" @click="sticker(s.name)"><img :src="s.url" alt="Add sticker"></button></div></template>
<template v-else-if="sheet==='moment-leave'"><h2><span class="moments-en">Leave this draft?</span><span class="moments-ko">이 초안을 나갈까요?</span></h2><p><span class="moments-en">Keep your draft on this device, or discard it before leaving.</span><span class="moments-ko">나가기 전에 이 기기에 초안을 보관하거나 삭제하세요.</span></p><button id="keep-moment-draft" class="primary ui-button ui-button--cards-delete" @click="leave(true)"><span class="moments-en">Keep draft</span><span class="moments-ko">초안 보관</span></button><button id="discard-moment-draft" class="row" @click="leave(false)"><span class="moments-en">Discard draft</span><span class="moments-ko">초안 삭제</span></button><button class="row" @click="sheet=''"><span class="moments-en">Continue editing</span><span class="moments-ko">계속 작성</span></button></template>
<template v-else-if="sheet==='moment-options'"><h2><span class="moments-en">Moment options</span><span class="moments-ko">순간 옵션</span></h2><button id="moment-visibility" class="row" @click="sheet='post-visibility'">Visibility <small>{{label(moment!.visibility)}} ›</small></button><button id="moment-category" class="row" @click="sheet='post-category'">Category <small>{{moment!.category}} ›</small></button><button id="delete-moment" class="row danger" @click="sheet='moment-delete'"><span class="moments-en">Delete moment</span><span class="moments-ko">순간 삭제</span></button></template>
<template v-else><h2>{{sheet==='card-remove'?'Remove this photo?':'Delete this moment?'}}</h2><p>This removes {{sheet==='card-remove'?'the image card from your profile.':'the published moment.'}}</p><button id="d5-confirm-delete" class="primary ui-button ui-button--cards-delete" :disabled="busy" @click="remove"><span class="moments-en">Delete</span><span class="moments-ko">삭제</span></button><button class="row" :disabled="busy" @click="sheet=''"><span class="moments-en">Cancel</span><span class="moments-ko">취소</span></button></template><p v-if="error" role="alert">{{error}}</p>
</section></Transition></div></Transition>
</section>
</template>
<style src="../styles/pages/cards.css"></style>
<style src="../styles/pages/moments.css"></style>
